// ============================================================================
// WTB_apb: APB4 register wrapper around WTB_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/WTB.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/WTB.md
// ============================================================================
module WTB_apb #(
  parameter int IDLE_TO = 300,
  parameter int CLAIM_WIN = 150,
  parameter int HOLD_WIN = 400,
  parameter int MAX_FR = 4
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rx_bit,
  output logic tx_bit,
  output logic tx_en
);
  localparam logic [31:0] ID_VALUE = 32'h57540200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[7] | hit[8] | hit[9] | hit[10])));   // core registers take whole words

  // ---------------- core ----------------
  logic [7:0]    c_my_addr;
  logic          c_cpu_we;
  logic [31:0]   c_cpu_wdata;
  logic          c_cpu_re;
  logic [31:0]   c_cpu_rdata;
  logic [3:0]    c_fifo_count;
  logic [3:0]    c_rx_count;
  logic          c_token_held;
  logic          c_irq;
  WTB_top #(.IDLE_TO(IDLE_TO), .CLAIM_WIN(CLAIM_WIN), .HOLD_WIN(HOLD_WIN), .MAX_FR(MAX_FR)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rx_bit(rx_bit),
    .tx_bit(tx_bit),
    .tx_en(tx_en),
    .my_addr(c_my_addr),
    .cpu_we(c_cpu_we),
    .cpu_addr((wr ? ((hit[7] ? 2'd0 : 2'd0) | (hit[8] ? 2'd1 : 2'd0) | (hit[9] ? 2'd2 : 2'd0) | (hit[10] ? 2'd3 : 2'd0)) : rd ? ((hit[11] ? 2'd0 : 2'd0)) : 2'd0)),
    .cpu_wdata(c_cpu_wdata),
    .cpu_re(c_cpu_re),
    .cpu_rdata(c_cpu_rdata),
    .fifo_count(c_fifo_count),
    .rx_count(c_rx_count),
    .token_held(c_token_held),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] r_MYADDR;   // 12'h014 MYADDR

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_MYADDR <= 8'h11;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_MYADDR <= (r_MYADDR & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_my_addr = r_MYADDR[7:0];
  // CORE: the core's register port (indices on the instance)
  assign c_cpu_we = wr & (PSTRB == 4'hF) & (hit[7] | hit[8] | hit[9] | hit[10]);
  assign c_cpu_wdata = PWDATA[31:0];
  assign c_cpu_re = rd & (hit[11]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_MYADDR);
      10'd6: apb_rdata = 32'({c_token_held, c_rx_count, c_fifo_count});
      10'd11: apb_rdata = 32'(c_cpu_rdata);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
